import numpy as np
raw=np.load('/app/output/jacobian_samples.npy',allow_pickle=True)
J=np.zeros((3,7)); bias=np.array([0,-.0011,-.0029])
for j,x in enumerate(raw):
 dq=np.array(x[0]); dx=np.array(x[1]); J[:,j]=(dx-bias)/dq[j]
print('J',J.round(3)); print('svd',np.linalg.svd(J)[1]);
for dx in [[.15,.05,-.08],[.1,.04,-.05],[0,.05,0],[.1,0,0]]:
 dx=np.array(dx); dq=J.T@np.linalg.solve(J@J.T+1e-3*np.eye(3),dx); print('dx',dx,'dq',dq.round(3),'Jdq',(J@dq).round(3))
